#!/usr/bin/env python3
"""Strict isolated build; --check compares every generated byte without changing the checkout."""
import argparse
import calendar
from datetime import datetime
import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
from check import ROOT, HELP, validate_content, validate_output
parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
count=validate_content()
env=dict(os.environ, SOURCE_DATE_EPOCH=str(calendar.timegm(datetime(2026,11,16).timetuple())), PYTHONHASHSEED='0')
with tempfile.TemporaryDirectory(prefix='pf-help-build-') as directory:
    output=Path(directory)/'site'
    subprocess.run([sys.executable,'-m','mkdocs','build','--strict','--clean','--config-file',str(HELP/'mkdocs.yml'),'--site-dir',str(output)],cwd=ROOT,env=env,check=True)
    # The custom MkDocs template uses only its own CSS/JS and the official search plugin.
    # Discard unused Bootstrap/theme assets, preserving generated search assets and licenses.
    for name in ['css','js','img','webfonts']:
        item=output/name
        if item.exists():shutil.rmtree(item)
    (output/'search/main.js').unlink(missing_ok=True) # The accessible client uses the official worker directly.
    validate_output(output)
    destination=ROOT/'public/ayuda'
    def inventory(path):
        return {str(p.relative_to(path)):hashlib.sha256(p.read_bytes()).hexdigest() for p in path.rglob('*') if p.is_file()}
    if args.check:
        built,committed=inventory(output),inventory(destination)
        changes=[name for name in set(built)|set(committed) if built.get(name)!=committed.get(name)]
        if changes:raise SystemExit('Generated help is stale: '+', '.join(sorted(changes)[:20])+'. Run help/scripts/build.py and review the output.')
        print(f'PASS reproducible build: {count} pages; generated files match byte for byte.')
    else:
        if destination.exists():shutil.rmtree(destination)
        shutil.copytree(output,destination)
        print(f'Built and validated {count} public help pages in public/ayuda/.')
